			before = catalogSnapshot(triples);
			try (var connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject());
				connection.commit();
			}
			assertTrue(selected.await(20, TimeUnit.SECONDS), "The real statement commit must reach its publisher");
			after = catalogSnapshot(triples);
			head = baseline + 1;
			byte[] actualStage;
			try (var input = triples.openBackupStage(head)) {
				actualStage = input.readAllBytes();
			}
			Stage stage;
			try (var input = new DataInputStream(new ByteArrayInputStream(actualStage))) {
				stage = PostCommitBackupPublisher.readStage(input, null);
			}
			assertEquals(head, stage.transaction);
			assertEquals(baseline, stage.previousTransaction);
			assertEquals(predecessor, stage.predecessor);
			assertEquals(1, stage.count);
			identity = stage.id;
			expectedStage = stageBytes(stage, statement);
			assertArrayEquals(expectedStage, actualStage,
					"The native source must contain the exact real mutation, transaction and predecessor");
			assertEquals(List.of(head), triples.listBackupStageTransactions(baseline, Long.MAX_VALUE));
