	private static CatalogSnapshot catalogSnapshot(TripleStore triples) throws IOException {
		return triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			var database = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, (ByteBuffer) null, 0, database));
			MDBStat statistics = MDBStat.malloc(stack);
			E(mdb_stat(transaction, database.get(0), statistics));
			var handle = stack.mallocPointer(1);
			E(mdb_cursor_open(transaction, database.get(0), handle));
			long cursor = handle.get(0);
			Map<String, byte[]> outboxDescriptors = new LinkedHashMap<>();
			byte[] explicitIndexDescriptor = null;
			byte[] mainHotRecord = null;
			MDBVal key = MDBVal.malloc(stack);
			MDBVal value = MDBVal.malloc(stack);
			try {
				int result = mdb_cursor_get(cursor, key, value, MDB_FIRST);
				while (result == MDB_SUCCESS) {
					byte[] keyBytes = copy(key);
					String name = new String(keyBytes, StandardCharsets.UTF_8);
					if (name.startsWith("backup-outbox")) {
						// Retain the opaque descriptor, including its native root; entry counts miss same-size
						// rewrites.
						outboxDescriptors.put(name, copy(value));
					} else if (name.equals(TripleIndex.nativeDatabaseName("spoc", true))) {
						explicitIndexDescriptor = copy(value);
					} else if (Arrays.equals(MAIN_HOT_KEY, keyBytes)) {
						mainHotRecord = copy(value);
					}
					result = mdb_cursor_get(cursor, key, value, MDB_NEXT);
				}
				E(result);
			} finally {
				mdb_cursor_close(cursor);
			}
			return new CatalogSnapshot(outboxDescriptors, explicitIndexDescriptor, mainHotRecord,
					statistics.ms_depth(), statistics.ms_leaf_pages(), statistics.ms_overflow_pages());
		});
	}

	private static byte[] copy(MDBVal value) {
		ByteBuffer bytes = Objects.requireNonNull(value.mv_data()).duplicate();
		byte[] copy = new byte[bytes.remaining()];
		bytes.get(copy);
		return copy;
	}

	private static byte[] mainHotRecord(long transaction, byte[] stage, int reservationBytes) {
		LmdbBackupChunkCodec.Encoder encoder = new LmdbBackupChunkCodec.Encoder();
		int frameLength = encoder.encode(stage, stage.length);
		assertTrue(frameLength <= 256, "The real statement fixture must fit a small native frame");
		int innerLength = 3 * Integer.BYTES + Long.BYTES + Integer.BYTES + frameLength;
		assertTrue(innerLength <= LmdbBackupCatalogTestSupport.packCapacity(reservationBytes));
		ByteBuffer record = ByteBuffer.allocate(reservationBytes).order(ByteOrder.BIG_ENDIAN);
		record.putInt(MAIN_HOT_MAGIC).putInt(innerLength);
		int innerOffset = record.position();
		record.putInt(PACK_MAGIC)
				.putInt(1)
				.putLong(transaction)
				.putInt(frameLength)
				.put(encoder.bytes(), 0, frameLength);
		CRC32C checksum = new CRC32C();
		checksum.update(record.array(), innerOffset, record.position() - innerOffset);
		record.putInt((int) checksum.getValue());
		return record.array();
	}

	private static byte[] stageBytes(Stage stage, Statement statement) throws IOException {
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		try (DataOutputStream output = new DataOutputStream(expected)) {
			PostCommitBackupPublisher.writeStageHeader(output, stage);
			LmdbBackupDeltaCodec.writeRecords(output, List.of(new Record(true, true, statement)));
		}
		return expected.toByteArray();
	}

	private static void assertPublished(LmdbStore store, Path backups, long baseline, UUID generation,
			Statement statement, Path destination) throws IOException {
		List<Path> logs = ((LmdbBackupServiceImpl) store.getBackupService()).exportTransactionLogs(backups, baseline,
				baseline + 1, destination);
		assertEquals(1, logs.size());
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		LmdbBackupDeltaCodec.write(expected, List.of(new Record(true, true, statement)), baseline, generation);
		try (var input = new GZIPInputStream(Files.newInputStream(logs.getFirst()))) {
			assertArrayEquals(expected.toByteArray(), input.readAllBytes(),
					"Normal archive export must preserve the exact committed record and predecessor");
		}
	}

	private static void assertContents(LmdbStore store, Statement statement) {
		try (var connection = store.getConnection()) {
			assertEquals(1L, connection.size());
			assertTrue(connection.hasStatement(statement.getSubject(), statement.getPredicate(), statement.getObject(),
					false));
		}
	}

	private record CatalogSnapshot(Map<String, byte[]> outboxDescriptors, byte[] explicitIndexDescriptor,
			byte[] mainHotRecord, int depth, long leafPages, long overflowPages) {
	}
